//! Multi-layer HT decode validation against Kakadu-generated codestreams.
//!
//! Kakadu (`kdu_compress Cmodes=HT Clayers=N`) is the only available encoder that emits multi-layer
//! HT codestreams (OpenHTJ2K's CLI hard-codes 1 layer). For a reversible (lossless) image, decoding
//! ALL layers must reconstruct the original exactly — so this test decodes each Kakadu file via the
//! jph-rs multi-layer path and asserts the samples equal the source PGM bit-for-bit.
//!
//! The test data lives outside the repo (regenerated by the dev harness); point `MLDIR` at the
//! directory holding `test.pgm` and `ml_<ORDER>.j2c`. The test is skipped (passes trivially) when
//! `MLDIR` is unset, so CI without the fixtures stays green.

use std::path::PathBuf;
mod common;

/// Parse a binary P5 PGM into `(width, height, samples-as-i32)`.
fn load_pgm(path: &PathBuf) -> (u32, u32, Vec<i32>) {
    common::pgm(path)
}


#[test]
#[ignore = "needs external conformance fixtures (env vars): run with --ignored"]
fn ml_decode_matches_kakadu_lossless() {
    let Ok(dir) = std::env::var("MLDIR") else {
        panic!("MLDIR unset — skipping Kakadu multi-layer validation");
    };
    let dir = PathBuf::from(dir);
    let (w, h, expected) = load_pgm(&dir.join("test.pgm"));

    // SL = single-layer Kakadu HT (isolates Kakadu-codestream compatibility from the multi-layer
    // path); the other five are the 3-layer multi-layer files, one per progression order.
    for ord in ["SL", "RPCL", "PCRL", "CPRL", "LRCP", "RLCP"] {
        let cs = std::fs::read(dir.join(format!("ml_{ord}.j2c")))
            .unwrap_or_else(|e| panic!("read ml_{ord}.j2c: {e}"));
        let img = jph_rs::mem::decode(&cs);
        assert_eq!(img.width, w, "{ord}: width");
        assert_eq!(img.height, h, "{ord}: height");
        assert_eq!(img.planes.len(), 1, "{ord}: component count");
        let got = &img.planes[0].samples;
        assert_eq!(got.len(), expected.len(), "{ord}: sample count");
        let mismatches = got.iter().zip(&expected).filter(|(a, b)| a != b).count();
        assert_eq!(mismatches, 0, "{ord}: {mismatches}/{} samples differ", expected.len());
        println!("{ord}: {} samples bit-exact", got.len());
    }
}

#[test]
#[ignore = "needs external conformance fixtures (env vars): run with --ignored"]
fn ml_decode_matches_kakadu_multi_size_multi_layer() {
    let Ok(dir) = std::env::var("MLDIR") else {
        panic!("MLDIR unset — skipping extended Kakadu multi-layer validation");
    };
    let dir = PathBuf::from(dir);
    let t2 = dir.join("t2.pgm");
    if !t2.exists() {
        panic!("t2.pgm absent — skipping extended validation");
    }
    let (w, h, expected) = load_pgm(&t2);

    // 200x130, 4 DWT levels, layer-innermost orders, 2/4/6 quality layers.
    let mut checked = 0;
    for ord in ["RPCL", "PCRL", "CPRL", "LRCP", "RLCP"] {
        for layers in [2u32, 4, 6] {
            let path = dir.join(format!("t2_{ord}_{layers}.j2c"));
            if !path.exists() {
                continue;
            }
            let cs = std::fs::read(&path).unwrap();
            let img = jph_rs::mem::decode(&cs);
            assert_eq!((img.width, img.height), (w, h), "{ord}/{layers}L: geometry");
            let got = &img.planes[0].samples;
            let mismatches = got.iter().zip(&expected).filter(|(a, b)| a != b).count();
            assert_eq!(mismatches, 0, "{ord}/{layers}L: {mismatches} samples differ");
            checked += 1;
            println!("{ord}/{layers}L: {} samples bit-exact", got.len());
        }
    }
    assert!(checked > 0, "no t2_*.j2c fixtures found");
}
